#include <vector>
#include <algorithm>

class Solution {
public:
    int minLightsToIlluminateRoad(int roadLength, std::vector<std::vector<int>>& lights) {
        std::sort(lights.begin(), lights.end());
        int count = 0, curEnd = 0, maxReach = 0, i = 0, n = lights.size();
        while (curEnd < roadLength) {
            while (i < n && lights[i][0] <= curEnd) {
                maxReach = std::max(maxReach, lights[i][1]);
                i++;
            }
            if (maxReach <= curEnd) return -1;
            curEnd = maxReach;
            count++;
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int minLightsToIlluminateRoad(int roadLength, int[][] lights) {
        Arrays.sort(lights, (a, b) -> Integer.compare(a[0], b[0]));
        int count = 0, curEnd = 0, maxReach = 0, i = 0, n = lights.length;
        while (curEnd < roadLength) {
            while (i < n && lights[i][0] <= curEnd) {
                maxReach = Math.max(maxReach, lights[i][1]);
                i++;
            }
            if (maxReach <= curEnd) return -1;
            curEnd = maxReach;
            count++;
        }
        return count;
    }
}

